content.css:
.tm {
  font-family: "Segoe UI", sans-serif;
  color: #1B3044;
  height: 100%;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 16px;
  box-sizing: border-box;
  background: #fff;
  border-radius: 16px;
  overflow: hidden;
}
.tm-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.tm-title {
  font-size: 17px;
  font-weight: 700;
  color: #082746;
}
.tm-status {
  font-size: 12px;
  font-weight: 600;
  color: #64748B;
}
.tm-status.ok {
  color: #16856A;
}
.tm-status.off {
  color: #C85B60;
}
.tm-ctx {
  font-size: 12px;
  color: #64748B;
}
.tm-form {
  display: flex;
  gap: 8px;
}
.tm-input {
  flex: 1;
  border: 1px solid #E6EDF3;
  border-radius: 12px;
  padding: 10px 14px;
  font-size: 14px;
  outline: none;
  transition: border-color 0.2s;
}
.tm-input:focus {
  border-color: #F58200;
}
.tm-btn {
  background: #F58200;
  color: #fff;
  border: 0;
  border-radius: 12px;
  padding: 0 18px;
  font-weight: 700;
  font-size: 14px;
  cursor: pointer;
  transition: background 0.2s;
}
.tm-btn:hover {
  background: #FFA51B;
}
.tm-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.tm-chip {
  background: #F1F5F9;
  border: 1px solid #E6EDF3;
  border-radius: 14px;
  padding: 5px 10px;
  font-size: 12px;
  color: #06436E;
  cursor: pointer;
}
.tm-chip:hover {
  border-color: #06436E;
}
.tm-out {
  flex: 1;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.tm-loading {
  font-size: 13px;
  color: #64748B;
  animation: tmp 1.2s ease-in-out infinite;
}
@keyframes tmp {
  50% {
    opacity: 0.4;
  }
}
.tm-meta {
  font-size: 12px;
  font-weight: 700;
  padding: 4px 10px;
  border-radius: 10px;
  align-self: flex-start;
  background: #F1F5F9;
}
.tm-meta.respondido {
  color: #16856A;
  background: #E8F5F0;
}
.tm-meta.bloqueado {
  color: #C85B60;
  background: #FBEDEE;
}
.tm-meta.sem_evidencia {
  color: #D99528;
  background: #FDF5E7;
}
.tm-ans {
  font-size: 14px;
  line-height: 1.45;
}
.tm-ev {
  border: 1px solid #E6EDF3;
  border-left: 3px solid #06436E;
  border-radius: 10px;
  padding: 8px 10px;
}
.tm-ev-h {
  font-size: 11px;
  font-weight: 700;
  color: #64748B;
}
.tm-ev-t {
  font-size: 13px;
}
.tm-err {
  font-size: 13px;
  color: #C85B60;
}
.tm-foot {
  font-size: 11px;
  color: #94A3B8;
}
